    count(*) FILTER (WHERE subflow_bwd_pkts < 0) AS subflow_bwd_pkts_neg, count(*) FILTER (WHERE subflow_bwd_pkts IN ('Infinity'::numeric, '-Infinity'::numeric)) AS subflow_bwd_pkts_inf, count(*) FILTER (WHERE subflow_bwd_pkts = 'NaN'::numeric) AS subflow_bwd_pkts_nan, count(*) FILTER (WHERE subflow_bwd_pkts IS NULL) AS subflow_bwd_pkts_null,
    count(*) FILTER (WHERE subflow_bwd_byts < 0) AS subflow_bwd_byts_neg, count(*) FILTER (WHERE subflow_bwd_byts IN ('Infinity'::numeric, '-Infinity'::numeric)) AS subflow_bwd_byts_inf, count(*) FILTER (WHERE subflow_bwd_byts = 'NaN'::numeric) AS subflow_bwd_byts_nan, count(*) FILTER (WHERE subflow_bwd_byts IS NULL) AS subflow_bwd_byts_null,
    count(*) FILTER (WHERE init_fwd_win_byts < 0) AS init_fwd_win_byts_neg, count(*) FILTER (WHERE init_fwd_win_byts IN ('Infinity'::numeric, '-Infinity'::numeric)) AS init_fwd_win_byts_inf, count(*) FILTER (WHERE init_fwd_win_byts = 'NaN'::numeric) AS init_fwd_win_byts_nan, count(*) FILTER (WHERE init_fwd_win_byts IS NULL) AS init_fwd_win_byts_null,
    count(*) FILTER (WHERE init_bwd_win_byts < 0) AS init_bwd_win_byts_neg, count(*) FILTER (WHERE init_bwd_win_byts IN ('Infinity'::numeric, '-Infinity'::numeric)) AS init_bwd_win_byts_inf, count(*) FILTER (WHERE init_bwd_win_byts = 'NaN'::numeric) AS init_bwd_win_byts_nan, count(*) FILTER (WHERE init_bwd_win_byts IS NULL) AS init_bwd_win_byts_null,
    count(*) FILTER (WHERE fwd_act_data_pkts < 0) AS fwd_act_data_pkts_neg, count(*) FILTER (WHERE fwd_act_data_pkts IN ('Infinity'::numeric, '-Infinity'::numeric)) AS fwd_act_data_pkts_inf, count(*) FILTER (WHERE fwd_act_data_pkts = 'NaN'::numeric) AS fwd_act_data_pkts_nan, count(*) FILTER (WHERE fwd_act_data_pkts IS NULL) AS fwd_act_data_pkts_null,
    count(*) FILTER (WHERE fwd_seg_size_min < 0) AS fwd_seg_size_min_neg, count(*) FILTER (WHERE fwd_seg_size_min IN ('Infinity'::numeric, '-Infinity'::numeric)) AS fwd_seg_size_min_inf, count(*) FILTER (WHERE fwd_seg_size_min = 'NaN'::numeric) AS fwd_seg_size_min_nan, count(*) FILTER (WHERE fwd_seg_size_min IS NULL) AS fwd_seg_size_min_null,
    count(*) FILTER (WHERE active_mean < 0) AS active_mean_neg, count(*) FILTER (WHERE active_mean IN ('Infinity'::numeric, '-Infinity'::numeric)) AS active_mean_inf, count(*) FILTER (WHERE active_mean = 'NaN'::numeric) AS active_mean_nan, count(*) FILTER (WHERE active_mean IS NULL) AS active_mean_null,
    count(*) FILTER (WHERE active_std < 0) AS active_std_neg, count(*) FILTER (WHERE active_std IN ('Infinity'::numeric, '-Infinity'::numeric)) AS active_std_inf, count(*) FILTER (WHERE active_std = 'NaN'::numeric) AS active_std_nan, count(*) FILTER (WHERE active_std IS NULL) AS active_std_null,
    count(*) FILTER (WHERE active_max < 0) AS active_max_neg, count(*) FILTER (WHERE active_max IN ('Infinity'::numeric, '-Infinity'::numeric)) AS active_max_inf, count(*) FILTER (WHERE active_max = 'NaN'::numeric) AS active_max_nan, count(*) FILTER (WHERE active_max IS NULL) AS active_max_null,
    count(*) FILTER (WHERE active_min < 0) AS active_min_neg, count(*) FILTER (WHERE active_min IN ('Infinity'::numeric, '-Infinity'::numeric)) AS active_min_inf, count(*) FILTER (WHERE active_min = 'NaN'::numeric) AS active_min_nan, count(*) FILTER (WHERE active_min IS NULL) AS active_min_null,
    count(*) FILTER (WHERE idle_mean < 0) AS idle_mean_neg, count(*) FILTER (WHERE idle_mean IN ('Infinity'::numeric, '-Infinity'::numeric)) AS idle_mean_inf, count(*) FILTER (WHERE idle_mean = 'NaN'::numeric) AS idle_mean_nan, count(*) FILTER (WHERE idle_mean IS NULL) AS idle_mean_null,
    count(*) FILTER (WHERE idle_std < 0) AS idle_std_neg, count(*) FILTER (WHERE idle_std IN ('Infinity'::numeric, '-Infinity'::numeric)) AS idle_std_inf, count(*) FILTER (WHERE idle_std = 'NaN'::numeric) AS idle_std_nan, count(*) FILTER (WHERE idle_std IS NULL) AS idle_std_null,
    count(*) FILTER (WHERE idle_max < 0) AS idle_max_neg, count(*) FILTER (WHERE idle_max IN ('Infinity'::numeric, '-Infinity'::numeric)) AS idle_max_inf, count(*) FILTER (WHERE idle_max = 'NaN'::numeric) AS idle_max_nan, count(*) FILTER (WHERE idle_max IS NULL) AS idle_max_null,
    count(*) FILTER (WHERE idle_min < 0) AS idle_min_neg, count(*) FILTER (WHERE idle_min IN ('Infinity'::numeric, '-Infinity'::numeric)) AS idle_min_inf, count(*) FILTER (WHERE idle_min = 'NaN'::numeric) AS idle_min_nan, count(*) FILTER (WHERE idle_min IS NULL) AS idle_min_null
FROM raw.{part}
WHERE clean.fix_ts(ts, capture_day) IS NOT NULL AND flow_duration >= 0;
